typedef AppIconContentType = String;

/// [AppManifest] 스키마입니다.
final ZodObject<AppManifest> appManifestSchema = z.object<AppManifest>({
  'handle': appHandleSchema,
  'name': z.string().trim().min(1).max(60),
  'description': z.string().trim().max(500).optional(),
  'iconUrl': z.string().url().pattern(RegExp(r'^https:\/\/.*'), format: 'starts_with').optional(),
  'supportEmail': z
      .string()
      .pattern(
          RegExp(
              r"^(?:[A-Za-z0-9_'+\-]+\.)*[A-Za-z0-9_'+\-]*[A-Za-z0-9_+-]@(?:[A-Za-z0-9][A-Za-z0-9\-]*\.)+[A-Za-z]{2,}$"),
          format: 'email')
      .optional(),
  'icon': z
      .string()
      .pattern(RegExp(r'^(?!\/)(?!.*\.\.)[A-Za-z0-9._/-]+$'))
      .refine((v) => RegExp(r'\.(png|svg)$', caseSensitive: false).hasMatch(v as String),
          message: '아이콘은 .png 또는 .svg 파일입니다')
      .optional(),
  'readme': z
      .string()
      .pattern(RegExp(r'^(?!\/)(?!.*\.\.)[A-Za-z0-9._/-]+$'))
      .refine((v) => RegExp(r'\.md$', caseSensitive: false).hasMatch(v as String), message: 'README는 .md 파일입니다')
      .optional(),
  'runtime': z.enum_(['code', 'external']).withDefault('code'),
  'external': appManifestExternalSchema.optional(),
  'mcp': appManifestMcpSchema.optional(),
  'scopes': z.array<String>(appScopeSchema).max(32).withDefault(const []),
  'network': appManifestNetworkSchema.withDefault(AppManifestNetwork.fromJson(const {'hosts': const []})),
  'events': z.array<String>(appEventTypeSchema).max(50).withDefault(const []),
  'ui': appManifestUiSchema.optional(),
  'http': appManifestHttpSchema.optional(),
  'schedules': z
      .record<AppManifestSchedulesValue>(appManifestSchedulesValueSchema)
      .refine((v) => keyCount(v) <= 10, message: '예약 작업은 10개까지입니다')
      .withDefault(const {}),
  'flow': appManifestFlowSchema.optional(),
  'settings': z
      .record<AppSettingField>(appSettingFieldSchema)
      .refine((v) => keyCount(v) <= 30, message: '설정 필드는 30개까지입니다')
      .withDefault(const {}),
  'secrets': z.array<String>(z.string().pattern(RegExp(r'^[A-Z][A-Z0-9_]{0,63}$'))).max(20).withDefault(const []),
}, AppManifest._);

/// AppManifest 값입니다.
class AppManifest extends ParsedObject {
  /// [AppManifest]을 만듭니다. 검증하지 않으므로 테스트·미리보기 데이터에 사용하십시오.
  AppManifest(
      {required String handle,
      required String name,
      String? description,
      String? iconUrl,
      String? supportEmail,
      String? icon,
      String? readme,
      String runtime = 'code',
      AppManifestExternal? external,
      AppManifestMcp? mcp,
      List<String> scopes = const [],
      AppManifestNetwork? network,
      List<String> events = const [],
      AppManifestUi? ui,
      AppManifestHttp? http,
      Map<String, AppManifestSchedulesValue> schedules = const {},
      AppManifestFlow? flow,
      Map<String, AppSettingField> settings = const {},
      List<String> secrets = const []})
      : super({
          'handle': handle,
          'name': name,
          if (description != null) 'description': description,
          if (iconUrl != null) 'iconUrl': iconUrl,
          if (supportEmail != null) 'supportEmail': supportEmail,
          if (icon != null) 'icon': icon,
          if (readme != null) 'readme': readme,
          'runtime': runtime,
          if (external != null) 'external': external,
          if (mcp != null) 'mcp': mcp,
          'scopes': scopes,
          'network': network ?? AppManifestNetwork.fromJson(const {'hosts': const []}),
          'events': events,
          if (ui != null) 'ui': ui,
          if (http != null) 'http': http,
          'schedules': schedules,
          if (flow != null) 'flow': flow,
          'settings': settings,
          'secrets': secrets
        });

  AppManifest._(super.json);

  /// JSON을 [appManifestSchema]로 검증해 만듭니다. 맞지 않으면 [ZodError]를 던집니다.
  factory AppManifest.fromJson(Map<String, Object?> json) => appManifestSchema.parse(json);

  Map<String, Object?> get _j => jsonOf(this);

  /// `handle` 값입니다.
  String get handle => _j['handle'] as String;

  /// `name` 값입니다.
  String get name => _j['name'] as String;

  /// `description` 값입니다.
  String? get description => _j['description'] as String?;

  /// https 이미지 주소. 동의 화면·상점 플랫폼 목록에 보입니다.
  String? get iconUrl => _j['iconUrl'] as String?;

  /// `supportEmail` 값입니다.
  String? get supportEmail => _j['supportEmail'] as String?;

  /// 앱 폴더의 아이콘 파일(PNG·SVG, 정사각형, PNG는 512px 이상, 256KB 이하). 있으면 `iconUrl`보다 먼저 보입니다.
  String? get icon => _j['icon'] as String?;

  /// 앱 상세에 보일 README(마크다운, 64KB 이하). 적지 않으면 앱 폴더의 README.md를 씁니다.
  String? get readme => _j['readme'] as String?;

  /// 실행 위치 — `code`(sayren이 실행) 또는 `external`(개발자 서버, 매뉴얼 「개발자 서버에서 실행」).
  String get runtime => _j['runtime'] as String;

  /// `runtime: external`의 호출 주소.
  AppManifestExternal? get external => _j['external'] as AppManifestExternal?;

  /// AI 에이전트 도구(매뉴얼 「에이전트 도구」).
  AppManifestMcp? get mcp => _j['mcp'] as AppManifestMcp?;

  /// 설치 때 전체 동의하는 스코프.
  List<String> get scopes => (_j['scopes'] as List).cast<String>();

  /// `network` 값입니다.
  AppManifestNetwork get network => _j['network'] as AppManifestNetwork;

  /// 이벤트 함수 구독.
  List<String> get events => (_j['events'] as List).cast<String>();

  /// `ui` 값입니다.
  AppManifestUi? get ui => _j['ui'] as AppManifestUi?;

  /// 공개 HTTP — 여기 적은 핸들러만 `https://{handle}.{앱 도메인}/hooks/{설치 id}/…`로 외부에서 부를 수 있습니다.
  AppManifestHttp? get http => _j['http'] as AppManifestHttp?;

  /// 예약 작업 — 이름마다 실행 간격.
  Map<String, AppManifestSchedulesValue> get schedules =>
      (_j['schedules'] as Map).cast<String, AppManifestSchedulesValue>();

  /// 주문 흐름 연동(매뉴얼 「주문 흐름에서 앱 쓰기」) — 흐름 알림(흐름 → 앱)과 흐름 사건(앱 → 흐름).
  AppManifestFlow? get flow => _j['flow'] as AppManifestFlow?;

  /// `settings` 값입니다.
  Map<String, AppSettingField> get settings => (_j['settings'] as Map).cast<String, AppSettingField>();

  /// 개발자 비밀 값 이름 — 값은 CLI(`sayren app secret put`)로 따로 넣습니다.
  List<String> get secrets => (_j['secrets'] as List).cast<String>();
}

