/// 판정용 요약 — `app_versions.capabilities`에 저장하고 분배·동의·넓어짐 판정이 매니페스트 전체 대신 읽습니다. 매니페스트에서만 만듭니다.
class AppCapabilities {
  /// [AppCapabilities]을 만듭니다.
  const AppCapabilities(
      {required this.scopes,
      required this.events,
      required this.networkHosts,
      required this.adminPage,
      this.publicHttp,
      this.schedules,
      this.flowNotifications,
      this.flowEvents,
      this.externalHost,
      this.tools,
      required this.requiredSettings,
      required this.secretSettings});

  /// `scopes` 값입니다.
  final List<String> scopes;

  /// `events` 값입니다.
  final List<AppEventType> events;

  /// `networkHosts` 값입니다.
  final List<String> networkHosts;

  /// `adminPage` 값입니다.
  final bool adminPage;

  /// 공개 HTTP 핸들러 키(`"GET /track/:id"`). 옛 버전 행에는 없습니다 — 읽을 때 `?? []`.
  final List<String>? publicHttp;

  /// 예약 작업 이름 → 간격. 옛 버전 행에는 없습니다 — 읽을 때 `?? {}`.
  final Map<String, AppScheduleInterval>? schedules;

  /// 흐름 알림(이름 → 표시 이름·매개변수)·흐름 사건(이름 → 표시 이름). 옛 버전 행에는 없습니다 — 읽을 때 `?? {}`.
  final Map<String, AppFlowNotification>? flowNotifications;

  /// `flowEvents` 값입니다.
  final Map<String, AppFlowEvent>? flowEvents;

  /// 외부 런타임의 호출 호스트(동의 화면). 코드 앱·옛 버전 행은 없습니다.
  final String? externalHost;

  /// 에이전트 도구. 옛 버전 행에는 없습니다 — 읽을 때 `?? {}`.
  final Map<String, AppTool>? tools;

  /// 필수 설정 키 — 하나라도 비어 있으면 이벤트 함수를 부르지 않습니다.
  final List<String> requiredSettings;

  /// `secretSettings` 값입니다.
  final List<String> secretSettings;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'scopes': scopes,
        'events': events,
        'networkHosts': networkHosts,
        'adminPage': adminPage,
        if (publicHttp != null) 'publicHttp': publicHttp,
        if (schedules != null) 'schedules': schedules,
        if (flowNotifications != null) 'flowNotifications': flowNotifications,
        if (flowEvents != null) 'flowEvents': flowEvents,
        if (externalHost != null) 'externalHost': externalHost,
        if (tools != null) 'tools': tools,
        'requiredSettings': requiredSettings,
        'secretSettings': secretSettings
      };
}

/// capability 레지스트리 — 키마다 동의 문단과 넓어짐 판정. 「넓어졌다」= 기존 설치가 재동의해야 새 버전으로 옮길 수 있습니다.
/// 동의 문단은 accounts 설치 화면·상점 플랫폼 앱 상세·유저 문서가 같은 문장을 씁니다.
class AppCapabilityDefinition {
  /// [AppCapabilityDefinition]을 만듭니다.
  const AppCapabilityDefinition({required this.key, required this.title, required this.describe, required this.widens});

  /// `key` 값입니다.
  final String key;

  /// 동의 화면의 문단 제목.
  final String title;

  /// 동의 화면에 보일 줄 — 없으면 문단을 그리지 않습니다.
  final List<String> Function(AppCapabilities) describe;

  /// 새 버전이 넓어졌는지입니다.
  final bool Function(AppCapabilities, AppCapabilities) widens;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {'key': key, 'title': title};
}
